   214→  /**
   215→   * Streaming text completion using the standard Chat Completions API.
   216→   * Chunks are delivered via `onChunk`; the resolved value is the full response.
   217→   *
   218→   * @throws {ProviderError} on API failure.
   219→   */
   220→  async stream(
   221→    request: LLMRequest,
   222→    config: LLMConfig,
   223→    onChunk: (chunk: LLMStreamChunk) => void
   224→  ): Promise<LLMResponse> {
   225→    const messages: OpenAI.Chat.ChatCompletionMessageParam[] = [
   226→      { role: 'system', content: request.systemPrompt },
   227→      ...request.messages.map((m) => ({
   228→        role: m.role as 'user' | 'assistant' | 'system',
   229→        content: m.content,
   230→      })),
   231→    ];
   232→
   233→    let fullContent = '';
   234→    let promptTokens = 0;
   235→    let completionTokens = 0;
   236→    let finishReason: LLMResponse['finishReason'] = 'stop';
   237→
   238→    try {
   239→      const stream = await this._getClient().chat.completions.create({
   240→        model: config.model,
   241→        messages,
   242→        max_tokens: request.maxTokens ?? config.maxTokens,
   243→        temperature: request.temperature ?? config.temperature,
   244→        top_p: config.topP,
   245→        presence_penalty: config.presencePenalty,
   246→        frequency_penalty: config.frequencyPenalty,
   247→        stream: true,
   248→        stream_options: { include_usage: true },
   249→      });
