   191→    if (!this._audioEngine.isRunning) return;
   192→
   193→    if (this._traceFirstAudio) {
   194→      this._traceFirstAudio = false;
   195→      console.log(`[V2 TRACE] 14. First outbound audio sent  sessionId=${this._sessionId}  responseId=${event.responseId}`);
