   221→   * (barge-in). Flushes the outbound pipeline and clears the transport buffer
   222→   * to stop audio playback immediately.
   223→   */
   224→  private _handleSpeechDetected(_event: BridgeSpeechDetectedEvent): void {
   225→    if (!this._audioEngine.isRunning) return;
