    33→ *
    34→ * 1. Loads campaign instructions from MongoDB.
    35→ * 2. Opens a real `IOpenAIRealtimeSession` via the DI-registered provider.
    36→ * 3. Creates a fresh `AudioEngine` for this call's pipeline.
    37→ * 4. Assembles the full `RuntimeIntegration` via `IntegrationFactory`.
    38→ * 5. Starts the integration — opens the OpenAI WebSocket, attaches
    39→ *    `TurnDiagnosticsCollector`, and starts inbound/outbound audio flows.
    40→ * 6. Registers a `transport.disconnected` listener to stop the integration
    41→ *    when the Exotel WebSocket closes.
    42→ *
    43→ * @param ctx - The pre-registered `SessionContext` from `createSession()`.
    44→ * @returns The started `IRuntimeIntegration`.
    45→ * @throws If `ctx.mediaSession` is null or the integration fails to start.
    46→ */
    47→export async function activateV2Session(ctx: SessionContext): Promise<IRuntimeIntegration> {
    48→  console.log(`[V2 TRACE] 4. activateV2Session() entered  sessionId=${ctx.sessionId}  campaignId=${ctx.campaignId}`);
    49→
    50→  if (!ctx.mediaSession) {
    51→    throw new Error(
    52→      `V2CallActivator: SessionContext ${ctx.sessionId} has no MediaSession — cannot activate.`
    53→    );
    54→  }
    55→
    56→  const logger = ctx.runtime.resolver.logger().child({
    57→    component: 'V2CallActivator',
    58→    sessionId: ctx.sessionId,
    59→  });
    60→
    61→  logger.info('Activating V2 session — loading campaign and opening provider session', {
    62→    sessionId: ctx.sessionId,
    63→    campaignId: ctx.campaignId,
    64→  });
    65→
    66→  // ── Step 1: Load campaign for system instructions ───────────────────────────
    67→  let instructions = '';
    68→  try {
    69→    const campaign = await storage.getCampaign(ctx.campaignId);
    70→    if (campaign) {
    71→      instructions = (campaign as any).ai_generated_script
    72→        || (campaign as any).script
    73→        || '';
    74→      logger.info('Campaign instructions loaded', {
    75→        campaignId: ctx.campaignId,
    76→        chars: instructions.length,
    77→      });
    78→    } else {
    79→      logger.warn('Campaign not found — proceeding with empty instructions', {
    80→        campaignId: ctx.campaignId,
    81→      });
    82→    }
    83→  } catch (err) {
    84→    logger.warn('Failed to load campaign data — proceeding with empty instructions', {
    85→      campaignId: ctx.campaignId,
    86→      error: String(err),
    87→    });
    88→  }
    89→
    90→  // ── Step 2: Open a real provider session ────────────────────────────────────
    91→  //
    92→  // `resolver.llm()` returns `ILLMProvider`.  In production the concrete type
    93→  // is always `OpenAIRealtimeProvider` (wired by CoordinatorBootstrap when
    94→  // OPENAI_API_KEY is present).  The cast is safe: V2 is only enabled when
    95→  // the provider was successfully registered.
    96→  const provider = ctx.runtime.resolver.llm() as unknown as OpenAIRealtimeProvider;
    97→  console.log(`[V2 TRACE] 5. OpenAIRealtimeProvider.openSession()  sessionId=${ctx.sessionId}`);
    98→  const providerSession = provider.openSession({ instructions });
    99→
   100→  logger.info('Provider session opened (unconnected — bridge will connect it)', {
   101→    sessionId: ctx.sessionId,
   102→    instructionsChars: instructions.length,
   103→  });
   104→
   105→  // ── Step 3: Create a fresh audio engine for this call's pipeline ─────────────
   106→  //
   107→  // This engine is independent of the stub AudioEngine that was placed inside
   108→  // the MediaSession at SessionFactory time.  RuntimeIntegration manages this
   109→  // engine's lifecycle via start() / stop() / destroy().
   110→  const audioEngine = createAudioEngine();
   111→
   112→  // ── Step 4: Assemble the full RuntimeIntegration ────────────────────────────
   113→  const integration = IntegrationFactory.create({
   114→    sessionId:    ctx.sessionId,
   115→    mediaSession: ctx.mediaSession,
   116→    audioEngine,
   117→    transport:    ctx.transportGateway,
   118→    providerSession,
   119→    logger:       ctx.runtime.resolver.logger(),
   120→  });
   121→
   122→  // ── Step 5: Start the integration ───────────────────────────────────────────
   123→  //   • AudioEngine starts
   124→  //   • RealtimeBridge.connect() → provider WebSocket opens → TurnDiagnosticsCollector attaches
   125→  //   • MediaSession.initialize() / start() (stub runtime → no-ops, safe)
   126→  //   • InboundAudioFlow and OutboundAudioFlow start
   127→  //   • SessionSupervisor starts
   128→  await integration.start();
   129→
   130→  logger.info('RuntimeIntegration started — [TURN-DIAGNOSTICS] collector is active', {
   131→    sessionId: ctx.sessionId,
   132→  });
   133→
   134→  // ── Step 6: Register cleanup on transport disconnect ─────────────────────────
   135→  //
   136→  // When Exotel closes the WebSocket, TransportGateway emits
   137→  // `transport.disconnected`.  Stopping the integration here guarantees
   138→  // RealtimeBridge.disconnect() fires, which:
   139→  //   • detaches TurnDiagnosticsCollector
   140→  //   • prints the [TURN-DIAGNOSTICS] CALL SUMMARY
   141→  //   • persists the JSON log to logs/call-diagnostics/
   142→  const onDisconnected = (event: TransportDisconnectedEvent): void => {
   143→    if (event.sessionId !== ctx.sessionId) return;
   144→
   145→    ctx.transportGateway.off('transport.disconnected', onDisconnected);
   146→
   147→    logger.info('Transport disconnected — stopping RuntimeIntegration', {
   148→      sessionId: ctx.sessionId,
   149→      code: event.code,
   150→      reason: event.reason,
   151→    });
   152→
   153→    integration.stop('transport_disconnected').catch(() => {
   154→      integration.shutdown();
   155→    });
   156→  };
   157→
   158→  ctx.transportGateway.on('transport.disconnected', onDisconnected);
   159→
   160→  return integration;
   161→}
