   483→    connection.onError((err) => {
   484→      this._logger.error('TransportConnection error', {
   485→        sessionId, error: err.message,
   486→      });
   487→      this._emitToSubscribers({
   488→        type: 'transport.error',
   489→        timestamp: Date.now(),
   490→        sessionId,
   491→        callSid,
   492→        errorCode: 'CONNECTION_ERROR',
   493→        errorMessage: err.message,
   494→        retryable: false,
