private _handleAudioReady(event: BridgeAudioReadyEvent): void {
  if (process.env.VOICE_ENGINE_DEBUG === 'true') {
    console.log(`[LIFECYCLE S8b] OutboundAudioFlow._handleAudioReady called  responseId=${event.responseId}  active=${this._active}  engineRunning=${this._audioEngine.isRunning}`);
  }

  if (!this._audioEngine.isRunning) {
    if (process.env.VOICE_ENGINE_DEBUG === 'true') {
      console.log('[LIFECYCLE S8c] [MISSING STEP] audioEngine.isRunning=false — audio dropped here. Engine was not started or has stopped.');
    }
    return;
  }

  if (process.env.VOICE_ENGINE_DEBUG === 'true') {
    console.log('[LIFECYCLE S8c] audioEngine.isRunning=true — guard passed');
  }

  if (this._traceFirstAudio) {
    this._traceFirstAudio = false;
    console.log(`[V2 TRACE] 14. First outbound audio sent  sessionId=${this._sessionId}  responseId=${event.responseId}`);
  }

  const chunk = this._buildChunk(event.base64Delta, event.timestamp);

  try {
    this._audioEngine.ingestOutbound(chunk);
    if (process.env.VOICE_ENGINE_DEBUG === 'true') {
      console.log(`[LIFECYCLE S8d] ingestOutbound OK  sequence=${chunk.sequence}`);
    }
  } catch (err) {
    this._logger.warn('OutboundAudioFlow: audioEngine.ingestOutbound failed', {
      error: String(err),
      sequence: chunk.sequence,
    });
    if (process.env.VOICE_ENGINE_DEBUG === 'true') {
      console.log(`[LIFECYCLE S8d] [MISSING STEP] ingestOutbound THREW  error=${String(err)}`);
    }
    return;
  }

  if (!this._config.tickOnIngest) return;

  const result = this._audioEngine.tickOutbound(null);

  if (process.env.VOICE_ENGINE_DEBUG === 'true') {
    console.log(`[LIFECYCLE S8e] tickOutbound → chunksToSend.length=${result.chunksToSend.length}${result.chunksToSend.length === 0 ? '  [MISSING STEP] no chunks produced — audio will not be sent' : ''}`);
  }

  for (const scheduled of result.chunksToSend) {
    if (process.env.VOICE_ENGINE_DEBUG === 'true') {
      console.log(`[LIFECYCLE S8f] calling transport.sendAudio  sessionId=${this._sessionId}  seq=${(scheduled as AudioChunk).sequence}`);
    }
    this._transport.sendAudio(this._sessionId, scheduled as AudioChunk);
  }
}

